"""Build and execute the reproducible, offline metric-suite notebook."""
from pathlib import Path
import os,json,sys
import nbformat
from nbclient import NotebookClient
ROOT=Path(__file__).resolve().parents[3];BASE=ROOT/'Experiment/09_offline_metric_suite'
md=nbformat.v4.new_markdown_cell;code=nbformat.v4.new_code_cell
cells=[md('# Four-metric scientific interaction suite\n\nSelected settings: off/155/001/003/046. Offline extraction from saved original Astra traces and native evaluations only. No new LLM calls, embeddings, annotations, or scientific runs. [Report](REPORT.md) · [Candidate caption and handoff](FIGURE_CAPTION.md) · [Plan](PLAN.md). Existing semantic, behavior, performance and recovery figures remain unchanged.'),
 code("from pathlib import Path\nimport sys,json,csv,subprocess\nfrom IPython.display import display,Markdown,Image,Code\nROOT=next(p for p in [Path.cwd(),*Path.cwd().parents] if (p/'Experiment/shared/task_selection.csv').exists())\nsys.path.insert(0,str(ROOT/'Experiment/09_offline_metric_suite/code'))\nimport extract,analyze,report,plot,self_repetition\nBASE=extract.BASE\nREEXTRACT=False  # Reads frozen local files only.\nRECOMPUTE=False  # Uses the saved extraction; no inference.\nif REEXTRACT or not (extract.DATA/'snapshot.json').exists(): extract.main()\nif RECOMPUTE or not (extract.DATA/'summary.json').exists(): analyze.main()\nsnap=json.loads((extract.DATA/'snapshot.json').read_text())\ns=json.loads((extract.DATA/'summary.json').read_text())\nreport.main()\nif REEXTRACT or RECOMPUTE or not (extract.DATA/'self_repetition_summary.json').exists(): self_repetition.main()\nsr=json.loads((extract.DATA/'self_repetition_summary.json').read_text())\nself_repetition.report(sr)\nprint(json.dumps({'policy':snap['policy'],'input_hashes':snap['provenance'],'bootstrap':s['bootstrap']},indent=2))"),
 md('## Coverage and matching\nAll metrics use original endpoints. Trace repetition uses a common panel with ≥2 complete traces for off/155/001 and ≥1 for 003/046; no invented within-persona repetitions for single-trial settings. Native outcome panels use all eligible original scores. Fact recovery uses only disambiguation; binary failure coverage uses only Bix correctness and SciConv FRR. Populations differ across panels and are explicitly reported.'),
 code("from collections import Counter\nprint('Original slots:',len(snap['scores']))\nprint('Complete traces:',sum(r.get('exclusion') is None for r in snap['traces']))\nprint('Saved recovery judgements:',sum(r['recovery'] is not None for r in snap['recovery']))\nprint('Repetition panel:',dict(Counter(r['source'] for r in s['repetition_coverage'])))\nprint('Failure panel:',dict(Counter(r['source'] for r in s['failure_panel'])))\ndisplay(Markdown(report.table(['Source','Off','155','001','003','046'],[[source,*[sum(r.get('exclusion') is None and r['source']==source and r['arm']==a for r in snap['traces']) for a in extract.ARMS]] for source in extract.SOURCES])))"),
 md('## Estimators\n**Repetition:** for each question, fraction of identical canonical event sequences across persona-rollout pairs; within-persona cells use distinct repeats only. Equal question weights within benchmark and equal benchmark weights in the aggregate. Lower repetition describes more structural variation, not better science. **Recovery:** saved recovered/total deleted-fact counts, averaged within case across observed trials. **Native scores:** retain each source’s native scale; paired contrasts require matching task/trial and compatible evaluators. **Failure coverage:** enumerate size-m off-trial subsets versus size-m distinct-persona subsets, choosing each persona’s available trial uniformly. At m=1,2,3, estimate expected fraction of questions with ≥1 native scientific failure. No best-performing/worst-performing persona subset is chosen. Study-cluster bootstrap CIs condition on the observed trials. No new significance tests.'),
 code("display(Markdown(report.table(['Setting','Complete-fact recovery [95% CI]','Matched change from off'],[[label,report.cell(report.pick(s['outcomes'],metric='complete_fact_recovery',arm=a,level='all',group='all')),'Reference' if a==extract.ARMS[0] else report.cell(report.pick(s['contrasts'],metric='complete_fact_recovery',persona_i=a,persona_j=extract.ARMS[0],level='all',group='all'))] for a,label in zip(extract.ARMS,extract.LABELS)])))\ndisplay(Markdown(report.table(['Benchmark','Budget','Off','Mixture','Matched difference'],[[report.NAMES[source],m,*[report.cell(report.pick(s['failure_coverage'],variant='primary',level='source',group=source,budget=m,strategy=strategy)) for strategy in ['off','mixture','difference']]] for source in ['bixbench','sciconvbench'] for m in [1,2,3]])))\nprint('Aggregate repetition:',json.dumps(s['repetition_overview'],indent=2))"),
 md('## Rendered figures\nMain and supporting figures use the established semantic-figure typography and persona palette. The earlier structural matrices remain supplementary; the current A compares each later message with earlier same-role messages within its own conversation. The revised main figure retains A/B/D: A is within-conversation self-repetition for simulator (filled circle) and actor (hollow square), B is a violin of case-level complete-recovery rates with mean/CI, and D shows individual settings on SciConv only. Native scores are reported separately. 003/046 stop at budget 1; no unavailable repeats are fabricated. All source data are retained. Shaded coverage bands are pointwise 95% CIs, not variation across independently regenerated campaigns.'),
 code("display(Code(Path(plot.__file__).read_text(),language='python'))\nplot.main()\nfor name in ['metric_suite','self_repetition_roles','repetition_by_benchmark','native_scores_with_ci']:\n    display(Image(filename=str(plot.FIG/(name+'.png')),width=1250))"),
 md('## Sensitivities and interpretation\nSame-length structural comparisons remove exchange-count differences but change eligible pair coverage. SciConv’s same-length patterns are identical by protocol construction; do not interpret its lower raw repetition as semantic strategy diversity. Intent-preserved failure coverage conditions on native intent flags, is secondary and does not prove full factual fidelity. Earlier recovery CIs used domain stratification; this integrated suite uses source-study clusters, so intervals can differ although means reproduce. Native absolute ASI scores mix historical evaluators; paired comparisons enforce corrected judges. Full methods and cell denominators are in REPORT.md.'),
 code("checks=subprocess.run([sys.executable,str(BASE/'code/test_metrics.py')],capture_output=True,text=True,check=True)\nprint(checks.stdout+checks.stderr)\nprint('Same-length SciConv matched pattern rates:',sorted({round(r['mean'],8) for r in s['repetition'] if r['variant']=='same_length' and r['level']=='source' and r['group']=='sciconvbench' and r['mean'] is not None}))\ndisplay(Markdown((BASE/'FIGURE_CAPTION.md').read_text()))")]

cells.insert(6, md('## Revised individual-setting coverage\nThe main figure replaces the mixture with each setting separately on the same 40 SciConv questions. Average all size-m subsets without replacement within each setting. Three-trial settings support budgets 1–3; 003/046 support only budget 1. The mixture table above remains supplementary. In B, a run scores 1 only if all annotated missing facts are recovered. Each dot is the percentage of complete-recovery runs for one case; the violin smooths these discrete proportions, and the black bar is a confidence interval for the equal-case mean. This is an endpoint change using existing runs, not a newly harder protocol.'))
cells.insert(7, code("display(Markdown(report.table(['Setting','Budget','Failed-task coverage [95% CI]'],[[extract.LABELS[extract.ARMS.index(r['arm'])],r['budget'],report.cell(r)] for r in s['persona_failure_coverage']])))"))

cells.insert(2, md('## Current A: within-conversation self-repetition\nEvery later length-eligible message is compared with earlier messages of the same role and episode. The score is the percentage of its 40-character normalized windows previously observed, averaged over later turns, then available trials within question. The common five-setting question panel uses equal source weights. This detects verbatim reuse, not semantic loops. Initial/context text, code fences and blockquotes are excluded. Short/single-message conversations are unavailable. The first message supplies history, never a self-comparison. Widths 20/80 are sensitivities. See SELF_REPETITION.md for all limits.'))
cells.insert(3, code("display(Markdown((BASE/'SELF_REPETITION.md').read_text()))\nprint(json.dumps(sr['method'],indent=2))"))

cells.insert(4, md('## Existing-data long-conversation sensitivity\nApply the same minimum of three or four length-eligible messages to every included episode, then retain common questions across the five settings. This is an exploratory length-conditioned subset, not selected by baseline repetition. Conversation length may itself depend on persona, and the source mix changes, so this does not estimate a causal effect or replace the representative panel. Actor and simulator text remain separate.'))
cells.insert(5, code("import analyze_long_traces\nanalyze_long_traces.main()\nlong=json.loads((extract.DATA/'long_trace_repetition.json').read_text())\ndisplay(Markdown(report.table(['Role','Min. messages','Setting','Questions','Repeated windows %'],[[r['role'],r['min_messages'],r['arm'],r['tasks'],round(r['mean'],4) if r['mean'] is not None else None] for r in long['cells'] if r['width']==40])))"))

def main():
 runtime=Path('/tmp/psb-analysis-jupyter');kernel=runtime/'kernels/python3';kernel.mkdir(parents=True,exist_ok=True)
 (kernel/'kernel.json').write_text(json.dumps({'argv':[str(ROOT/'.venv/bin/python'),'-m','ipykernel_launcher','-f','{connection_file}'],'display_name':'Python (PersonaScienceBench)','language':'python'}))
 os.environ.update(JUPYTER_PATH=str(runtime),JUPYTER_RUNTIME_DIR=str(runtime/'runtime'),IPYTHONDIR=str(runtime/'ipython'),MPLCONFIGDIR='/tmp/psb-mpl',OPENBLAS_NUM_THREADS='1',OMP_NUM_THREADS='1')
 nb=nbformat.v4.new_notebook(cells=cells,metadata={'kernelspec':{'name':'python3','display_name':'Python (PersonaScienceBench)','language':'python'}})
 path=BASE/'metric_suite.ipynb';nbformat.write(nb,path)
 NotebookClient(nb,timeout=600,startup_timeout=90,kernel_name='python3',resources={'metadata':{'path':str(ROOT)}}).execute()
 nbformat.validate(nb);nbformat.write(nb,path);print('Executed offline metric notebook:',sum(c.cell_type=='code' for c in nb.cells),'code cells',flush=True)
if __name__=='__main__':main()
